def graph_status_from_stage_runs(apps: Any, schema_editor: Any) -> None:
    """Indexed documents get the outcome of their last graph run; a failed one is pending.

    Documents indexed by 1.0.0-rc.2 while Neo4j was down kept `indexed` with the graph stage
    failed; as `pending`, the `recover` task projects them once Neo4j answers.
    """

    Document = apps.get_model("catalogue", "Document")
    batch = []
    rows = Document.objects.filter(status="indexed").only("id", "stage_runs")
    for doc in rows.iterator(chunk_size=500):
        runs = [r for r in doc.stage_runs or [] if r.get("stage") == "graph"]
        if not runs:
            continue
        doc.graph_status = {"ok": "ok", "failed": "pending"}.get(runs[-1].get("outcome"), "")
        batch.append(doc)
        if len(batch) >= 500:
            Document.objects.bulk_update(batch, ["graph_status"])
            batch = []
    if batch:
        Document.objects.bulk_update(batch, ["graph_status"])


